    33→/// <summary>
    34→/// Provides an execution payload handler as defined in Engine API
    35→/// <a href="https://github.com/ethereum/execution-apis/blob/main/src/engine/shanghai.md#engine_newpayloadv2">
    36→/// Shanghai</a> specification.
    37→/// </summary>
    38→public sealed class NewPayloadHandler : IAsyncHandler<ExecutionPayload, PayloadStatusV1>, IDisposable
    39→{
    40→    private readonly IPayloadPreparationService _payloadPreparationService;
    41→    private readonly IBlockValidator _blockValidator;
    42→    private readonly IBlockTree _blockTree;
    43→    private readonly IPoSSwitcher _poSSwitcher;
    44→    private readonly IBeaconSyncStrategy _beaconSyncStrategy;
    45→    private readonly IBeaconPivot _beaconPivot;
    46→    private readonly IBlockCacheService _blockCacheService;
    47→    private readonly IBlockProcessingQueue _processingQueue;
    48→    private readonly IMergeSyncController _mergeSyncController;
    49→    private readonly IInvalidChainTracker _invalidChainTracker;
    50→    private readonly IStateReader _stateReader;
    51→    private readonly ILogger _logger;
    52→    private readonly LruCache<ValueHash256, (bool valid, string? message)>? _latestBlocks;
    53→    private readonly ProcessingOptions _defaultProcessingOptions;
    54→    private readonly TimeSpan _timeout;
    55→
    56→    private readonly ConcurrentDictionary<Hash256, ValidationCompletion> _blockValidationTasks = new();
    57→
    58→    private long _lastBlockNumber;
    59→    private long _lastBlockGasLimit;
    60→    private readonly bool _simulateBlockProduction;
    61→
    62→    public NewPayloadHandler(
    63→        IPayloadPreparationService payloadPreparationService,
    64→        IBlockValidator blockValidator,
    65→        IBlockTree blockTree,
    66→        IPoSSwitcher poSSwitcher,
    67→        IBeaconSyncStrategy beaconSyncStrategy,
    68→        IBeaconPivot beaconPivot,
    69→        IBlockCacheService blockCacheService,
    70→        IBlockProcessingQueue processingQueue,
    71→        IInvalidChainTracker invalidChainTracker,
    72→        IMergeSyncController mergeSyncController,
    73→        IMergeConfig mergeConfig,
    74→        IReceiptConfig receiptConfig,
    75→        IStateReader stateReader,
    76→        ILogManager logManager)
    77→    {
    78→        _payloadPreparationService = payloadPreparationService;
    79→        _blockValidator = blockValidator ?? throw new ArgumentNullException(nameof(blockValidator));
    80→        _blockTree = blockTree;
    81→        _poSSwitcher = poSSwitcher;
    82→        _beaconSyncStrategy = beaconSyncStrategy;
    83→        _beaconPivot = beaconPivot;
    84→        _blockCacheService = blockCacheService;
    85→        _processingQueue = processingQueue;
    86→        _invalidChainTracker = invalidChainTracker;
    87→        _mergeSyncController = mergeSyncController;
    88→        _stateReader = stateReader;
    89→        _logger = logManager.GetClassLogger();
    90→        _defaultProcessingOptions = receiptConfig.StoreReceipts ? ProcessingOptions.EthereumMerge | ProcessingOptions.StoreReceipts : ProcessingOptions.EthereumMerge;
    91→        _timeout = TimeSpan.FromMilliseconds(mergeConfig.NewPayloadBlockProcessingTimeout);
    92→        if (mergeConfig.NewPayloadCacheSize > 0)
    93→            _latestBlocks = new(mergeConfig.NewPayloadCacheSize, 0, "LatestBlocks");
    94→        _simulateBlockProduction = mergeConfig.SimulateBlockProduction;
    95→        _processingQueue.BlockRemoved += GetProcessingQueueOnBlockRemoved;
    96→    }
